            var model = GuildBinder.CreateModel((string.IsNullOrEmpty(item.GuildModelName) ? default(GuildId) : new GuildId(item.GuildModelName)), item.GuildName);
            ApplyGuildGuildUserItemTo(model, item);
            var binder = new GuildBinder(model, _gs2, _session, _mountSurface: GuildMountSurface.GuildGuildUser);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyGuildGuildUserItemTo(MutableGuild model, Gs2.Unity.Gs2Guild.Model.EzJoinedGuild item)
        {
            GuildBinder.ApplyUserdataGuildGuildGuildModel(model, item);
        }

        private GuildId ExtractGuildGuildUserIdentity(Gs2.Unity.Gs2Guild.Model.EzJoinedGuild item)
        {
            return (string.IsNullOrEmpty(item.GuildModelName) ? default(GuildId) : new GuildId(item.GuildModelName));
        }

        private string? ExtractGuildGuildUserRowKey(Gs2.Unity.Gs2Guild.Model.EzJoinedGuild item)
        {
            var id = ExtractGuildGuildUserIdentity(item);
            if (EqualityComparer<GuildId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.GuildModelName) || string.IsNullOrEmpty(item.GuildName)) return null;
            return $"{item.GuildModelName}.{item.GuildName}";
        }

        internal sealed class GuildBinderComparer : IComparer<IReadOnlyGuildBinder>
        {
            public static readonly GuildBinderComparer Default = new GuildBinderComparer();
            public int Compare(IReadOnlyGuildBinder? a, IReadOnlyGuildBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<GuildId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class GuildBinderIdTieBreakComparer : IComparer<IReadOnlyGuildBinder>
        {
            private readonly IComparer<IReadOnlyGuildBinder> _inner;
            public GuildBinderIdTieBreakComparer(IComparer<IReadOnlyGuildBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyGuildBinder? a, IReadOnlyGuildBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<GuildId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
